/**
 * LRU cache with TTL. Entries expire after ttlMs; the cache holds at most
 * `capacity` entries and evicts the least-recently-used one when full.
 * Recency is tracked by Map insertion order: the first key is the least
 * recently used, the last is the most recently used.
 */
export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      entry.lastUsed = now
      // move to the end so the cache knows it was just used
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) {
        entries.delete(key)
      } else if (entries.size >= capacity) {
        // evict the least-recently-used entry (first in Map order)
        const oldestKey = entries.keys().next().value
        entries.delete(oldestKey)
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },
    size() {
      return entries.size
    },
    _raw() {
      return [...entries.entries()]
    },
  }
}
